// Finds the row to turn into a draft, validates it and builds the Etsy request. Nothing is sent to Etsy here.
const cfg = $('Config').first().json;
const res = $('Read Tab').first().json;
const nk = s => String(s == null ? '' : s).toLowerCase().replace(/[^a-z0-9]/g, '');
const letters = n => { let s = ''; n += 1; while (n > 0) { const m = (n - 1) % 26; s = String.fromCharCode(65 + m) + s; n = Math.floor((n - 1) / 26); } return s; };
const out = (o) => [{ json: o }];
const apiKey = String(cfg.apiKey || '').trim();
if (!/^[^\s:]+:[^\s:]+$/.test(apiKey) || /PASTE|SHARED_SECRET_HERE/i.test(apiKey)) return out({ ok: false, problems: ['Config apiKey is not set: it must be keystring:shared_secret (paste it in n8n only, never in the repo)'], warnings: [] });
if (res.error || !res.values) return out({ ok: false, problems: ['could not read the tab: ' + JSON.stringify(res.error || 'no data').slice(0, 200)], warnings: [] });
const rows = res.values;
const hk = (rows[0] || []).map(nk);
const ix = name => hk.indexOf(nk(name));
const get = (r, name) => { const i = ix(name); return i < 0 || r[i] == null ? '' : r[i]; };
const str = (r, name) => String(get(r, name)).trim();
const num = v => { const n = parseFloat(String(v == null ? '' : v).replace(/[^0-9.\-]/g, '')); return isFinite(n) ? n : 0; };
const yes = v => /^(yes|true|1)$/i.test(String(v || '').trim());
const skuCol = hk.lastIndexOf('productno');
// Etsy category per tab, confirmed with the read-only category check (2026-11). 'table' = chosen from the title.
const TAB_CAT = { Bathtub: 11353, Sink: 11353, 'Marble+ Basin': 11353, Fireplace: 12219, Vanity: 903, 'Marble+ ConsoleTable': 11355, Bench: 12369, Lamppost: 12410, Statue: 2869, Animal: 2869, Carving: 129, Table: 'table',
  Moulding: 784, DoorSurround: 784, WindowSurround: 784, OutdoorCornice: 784, Columns: 784, Balustrade: 784, Stairs: 784, Wainscoting: 784, 'Wall-Coverings': 784, MarbleRangeHood: 784,
  StoneMosaicTile: 781, MarbleMedallion: 781, MarbleSlab: 781, BookMatchedSlabs: 781, Fountain: 12240, Planter: 6061, 'Exterior-Wall-Decoration': 2784 };
// mat = material property id (marble is value 171 in every list). dims: 'whd' = Width/Height/Depth, 'wl' = Width/Length, '' = none (size goes in the description). craft = required Craft type value.
const M1 = 148789511893;
const CAT = { 11353: { mat: 570246212865, dims: 'whd' }, 12219: { mat: M1, dims: 'whd' }, 903: { mat: M1, dims: 'whd' }, 11355: { mat: M1, dims: 'whd' }, 12369: { mat: M1, dims: 'whd' }, 12410: { mat: M1, dims: 'whd' }, 2869: { mat: M1, dims: 'whd' },
  129: { mat: 570246213483, dims: 'whd' }, 977: { mat: M1, dims: 'whd' }, 12371: { mat: M1, dims: 'whd' }, 12372: { mat: M1, dims: 'whd' },
  784: { mat: M1, dims: 'whd', craft: 560 }, 781: { mat: M1, dims: 'wl', craft: 560 },
  12240: { mat: M1, dims: '' }, 6061: { mat: M1, dims: '' }, 2784: { mat: M1, dims: '' } };
const PROP = { width: 47626759898, height: 47626759834, depth: 54142602037, length: 47626759838, craft: 47626759760 };
const problems = [], warnings = [];
const baseTax = TAB_CAT[cfg.tab];
if (!baseTax) return out({ ok: false, problems: ['tab "' + cfg.tab + '" has no Etsy category set up (set up: ' + Object.keys(TAB_CAT).join(', ') + ')'], warnings });
if (skuCol < 0) return out({ ok: false, problems: ['no Product No. column'], warnings });
const want = String(cfg.sku || '').trim().toUpperCase();
const count = {};
for (let i = 1; i < rows.length; i++) { const s = String((rows[i] || [])[skuCol] || '').trim().toUpperCase(); if (s) count[s] = (count[s] || 0) + 1; }
let hit = -1;
for (let i = 1; i < rows.length; i++) {
  const r = rows[i] || [];
  const s = String(r[skuCol] || '').trim().toUpperCase();
  if (!s) continue;
  if (want) { if (s === want) { hit = i; break; } continue; }
  if (yes(str(r, 'Etsy_ready_to_post')) && !str(r, 'Etsy_listing_id') && !str(r, 'Etsy_status')) { hit = i; break; }
}
if (hit < 0) return out({ ok: false, problems: [want ? 'SKU ' + want + ' not found in ' + cfg.tab : 'no row in ' + cfg.tab + ' is flagged Etsy_ready_to_post = yes without an Etsy listing'], warnings });
const r = rows[hit];
const sku = String(r[skuCol]).trim();
let tax = baseTax;
if (tax === 'table') { const tt = (str(r, 'Title_Etsy') + ' ' + str(r, 'Title_Shopify')).toLowerCase(); if (/coffee|cocktail/.test(tt)) tax = 12371; else if (/end table|side table|accent table|bedside|nightstand/.test(tt)) tax = 12372; else { tax = 977; if (!/dining|kitchen|dinner|conference/.test(tt)) warnings.push('table type not clear from the title: used Kitchen & Dining Tables'); } }
const cat = CAT[tax];
// Which sheet size fills which Etsy field (first one with a value wins). Anything else goes into a line in the description.
const SRC = { Moulding: { width: ['Length'], height: ['Height'], depth: ['Thickness'] }, OutdoorCornice: { width: ['Length'], height: ['Height'], depth: ['Projection'] },
  Wainscoting: { width: ['Width'], height: ['Length', 'Height'], depth: ['Thickness', 'Depth'] }, 'Wall-Coverings': { width: ['Width'], height: ['Length', 'Height'], depth: ['Thickness', 'Depth'] },
  Balustrade: { width: ['Width', 'Handrail Width', 'Base/Plinth Width'], height: ['Overall Height', 'Height'], depth: ['Depth', 'Baluster Diameter'] }, Stairs: { width: ['Width'], height: ['Height'] } };
const DEFAULT_SRC = cat.dims === 'wl' ? { width: ['Width'], length: ['Length', 'Depth'] } : { width: ['Width'], height: ['Height'], depth: ['Depth', 'Length'] };
const src = cat.dims === '' ? {} : (cat.dims === 'whd' && SRC[cfg.tab] ? SRC[cfg.tab] : DEFAULT_SRC);
const usedFields = new Set(), mapped = {};
Object.entries(src).forEach(([k, fields]) => { mapped[k] = 0; for (const fl of fields) { const v = num(get(r, fl + ' Inch')); if (v > 0) { mapped[k] = v; usedFields.add(fl); break; } } });
const MEAS = ['Length', 'Width', 'Height', 'Depth', 'Thickness', 'Projection', 'Diameter', 'Inner Opening Diameter', 'Overall Height', 'Handrail Height', 'Handrail Width', 'Baluster Diameter', 'Baluster Height', 'Base/Plinth Width', 'Base/Plinth Height'];
const measParts = skipUsed => { const parts = []; MEAS.forEach(L => { if (skipUsed && usedFields.has(L)) return; const cm = num(get(r, L + ' CM')), inch = num(get(r, L + ' Inch')); if (cm > 0 || inch > 0) parts.push(L.toLowerCase() + ' ' + (cm > 0 ? Math.round(cm * 10) / 10 + ' cm' : '') + (cm > 0 && inch > 0 ? ' / ' : '') + (inch > 0 ? Math.round(inch * 100) / 100 + ' in' : '')); }); return parts; };
const WRITE = ['Etsy_listing_id', 'Etsy_url', 'Etsy_admin_url', 'Etsy_status', 'Etsy_error', 'Etsy_created_at', 'Etsy_price_cad', 'Etsy_category_id', 'Etsy_image_count', 'Etsy_synced_at', 'Etsy_ready_to_post'];
const writeCols = {};
WRITE.forEach(n => { const i = ix(n); if (i < 0) problems.push('missing column ' + n); else writeCols[nk(n)] = letters(i); });
if (count[sku.toUpperCase()] > 1) problems.push('SKU appears ' + count[sku.toUpperCase()] + ' times in this tab');
if (str(r, 'Etsy_listing_id')) problems.push('row already has Etsy_listing_id ' + str(r, 'Etsy_listing_id'));
const title = str(r, 'Title_Etsy');
if (!title) problems.push('no Title_Etsy'); else if (title.length > 140) problems.push('title is ' + title.length + ' characters (max 140)');
const specials = (title.match(/[&%:]/g) || []).length;
if (specials > 1) warnings.push('title uses & % : more than once (' + specials + '); Etsy may reject it');
let description = str(r, 'Description_Etsy');
description = description.replace(/\*\*|__/g, '').replace(/^#{1,6}\s+/gm, '');
// Dimensions block (cm / inch) on top, only for categories where Etsy has no size fields (as in the client's video); then the text, then the product number.
if (description && cat.dims === '' && !/^\s*dimensions/i.test(description)) {
  const WHD = ['Width', 'Height', 'Depth'], LWT = ['Length', 'Width', 'Thickness'];
  const DIM_LABELS = { Fireplace: WHD, MarbleRangeHood: WHD, Carving: WHD, WindowSurround: WHD, Moulding: ['Length', 'Height', 'Thickness'], OutdoorCornice: ['Length', 'Height', 'Projection'],
    Stairs: ['Width', 'Height', 'Diameter', 'Inner Opening Diameter'], Balustrade: ['Overall Height', 'Handrail Height', 'Handrail Width', 'Baluster Diameter', 'Baluster Height', 'Base/Plinth Width', 'Base/Plinth Height'],
    BookMatchedSlabs: ['Length', 'Width'], MarbleSlab: LWT, 'Wall-Coverings': LWT, StoneMosaicTile: LWT, MarbleMedallion: LWT, 'Exterior-Wall-Decoration': LWT, Wainscoting: LWT };
  const labels = DIM_LABELS[cfg.tab] || ['Length', 'Width', 'Height'];
  const lines = [];
  labels.forEach(L => { const cm = num(get(r, L + ' CM')), inch = num(get(r, L + ' Inch')); const bits = []; if (cm > 0) bits.push(String(Math.round(cm * 10) / 10)); if (inch > 0) bits.push((Math.round(inch * 100) / 100).toFixed(2)); if (bits.length) lines.push(L + ': ' + bits.join(' / ')); });
  if (lines.length) description = 'Dimensions (cm/Inch)\n' + lines.join('\n') + '\n\n' + description; else warnings.push('no sizes for the Dimensions block');
}
// Minimum order (Luna, 2026-11-04): whole category. Etsy has no minimum-order field, so it goes on top of the description.
const MOQ = { Moulding: 3, OutdoorCornice: 3, StoneMosaicTile: 50 };
if (description && MOQ[cfg.tab] && !/^\s*minimum order/i.test(description)) description = 'Minimum order: ' + MOQ[cfg.tab] + ' pieces\n\n' + description;
if (description && !/Product No:/i.test(description)) description += '\n\nProduct No: ' + sku;
const price = num(get(r, 'Price In CAD'));
if (!(price > 0)) problems.push('no valid Price In CAD');
// Same rule as the Shopify sync: two photos are the same only when the URLs are identical after removing Shopify's v= cache-buster. No filename guessing.
const normUrl = u => { const s = String(u || ''); const q = s.indexOf('?'); if (q === -1) return s; const base = s.slice(0, q); const kept = s.slice(q + 1).split('&').filter(p => p && !/^v=/.test(p)).join('&'); return kept ? base + '?' + kept : base; };
const cad = str(r, 'IMAGE URL11');
const cadKey = /^https?:/i.test(cad) ? normUrl(cad) : '';
const imgs = [], seen = new Set();
for (let k = 1; k <= 10; k++) {
  const u = str(r, 'IMAGE URL' + k);
  if (!/^https?:/i.test(u)) continue;
  const key = normUrl(u);
  if (cadKey && key === cadKey) { warnings.push('IMAGE URL' + k + ' is the same file as the CAD drawing: kept once, at the end'); continue; }
  if (seen.has(key)) { warnings.push('IMAGE URL' + k + ' repeats an earlier photo: skipped'); continue; }
  seen.add(key); imgs.push({ url: u, label: 'IMAGE URL' + k });
}
if (cadKey) imgs.push({ url: cad, label: 'IMAGE URL11 (CAD drawing)' });
imgs.forEach((x, i) => { x.rank = i + 1; });
if (!imgs.length) problems.push('no photos');
if (!/^https?:/i.test(cad)) warnings.push('no CAD drawing in IMAGE URL11');
const tags = [];
str(r, 'Tags_Etsy').split(/[,;\n|]+/).forEach(t => { t = t.replace(/[^\p{L}\p{N} \-']/gu, '').replace(/\s+/g, ' ').trim(); if (t && t.length <= 20 && !tags.some(x => x.toLowerCase() === t.toLowerCase())) tags.push(t); });
if (tags.length < 13) { const msg = 'only ' + tags.length + ' tags (Etsy allows 13); run the tag generator first'; if (cfg.requireFullTags === true) problems.push(msg); else warnings.push(msg); }
if (tags.length > 13) tags.length = 13;
const who = str(r, 'who_made') || 'collective', when = str(r, 'when_made') || 'made_to_order';
const weight = num(get(r, 'Weight KG'));
if (!(weight > 0)) warnings.push('no Weight KG');
const QTY_BY_TAB = { Moulding: 999, OutdoorCornice: 999, StoneMosaicTile: 999 };
const listingQty = QTY_BY_TAB[cfg.tab] || 1;
const listing = { quantity: listingQty, title, description, price, who_made: who, when_made: when, taxonomy_id: tax, shipping_profile_id: Number(cfg.shippingProfileId), readiness_state_id: Number(cfg.readinessStateId), type: 'physical', is_supply: false };
if (tags.length) listing.tags = tags;
if (weight > 0) { listing.item_weight = weight; listing.item_weight_unit = 'kg'; }
const pickPolicy = (cfgId, RP) => { const id = String(cfgId || '').trim(); if (/^\d+$/.test(id)) return { id: Number(id) }; const list = RP && Array.isArray(RP.results) ? RP.results : []; const ok = list.filter(x => x.accepts_returns === true && Number(x.return_deadline) === 30); if (ok.length === 1) return { id: Number(ok[0].return_policy_id) }; return { error: RP && RP.error ? 'could not read the shop return policies (' + JSON.stringify(RP.error).slice(0, 120) + ')' : ok.length + ' return policies with returns accepted and 30 days found (need exactly 1); set returnPolicyId in Config' }; };
{ let RP = null; try { RP = $('Get Return Policies').first().json; } catch (e) { RP = null; } const pol = pickPolicy(cfg.returnPolicyId, RP); if (pol.id) listing.return_policy_id = pol.id; else warnings.push('no return policy set (' + pol.error + '): the listing is created without one'); }

const properties = [{ id: cat.mat, name: 'material', body: { value_ids: [171], values: ['Marble'] } }];
if (cat.craft) properties.push({ id: PROP.craft, name: 'craft type', body: { value_ids: [cat.craft], values: [] } });
const dv = (v, name) => { if (v > 0) properties.push({ id: PROP[name], name, body: { value_ids: [], values: [String(Math.round(v * 100) / 100)], scale_id: 5 } }); else warnings.push('no ' + name + ' (inches)'); };
if (cat.dims === 'whd') { dv(mapped.width, 'width'); dv(mapped.height, 'height'); dv(mapped.depth, 'depth'); }
if (cat.dims === 'wl') { dv(mapped.width, 'width'); dv(mapped.length, 'length'); }
return out({ ok: problems.length === 0, problems, warnings, tab: cfg.tab, row: hit + 2, sku, title, priceCad: price, taxonomyId: tax, tags, listing, properties, images: imgs, quantity: listingQty, expectedImages: imgs.length, writeCols, descriptionChars: description.length });

const p = $input.first().json;
const cfg = $('Config').first().json;
const { listing, ...rest } = p;
const preview = listing ? { ...listing, description: String(listing.description || '').slice(0, 300) + (String(listing.description || '').length > 300 ? ' ...' : '') } : null;
return [{ json: { dryRun: cfg.dryRun !== false, message: !p.ok ? 'NOT READY: fix the problems below. Nothing was sent to Etsy.' : (cfg.dryRun !== false ? 'DRY RUN: nothing was sent to Etsy. Set dryRun to false in Config to create this draft.' : ''), ...rest, listingPreview: preview } }];

const p = $('Pick Row').first().json;
const c = $input.first().json;
return p.properties.map(x => ({ json: { listing_id: c.listing_id, property_id: x.id, name: x.name, body: x.body } }));

const p = $('Pick Row').first().json;
const lid = $('Prep Properties').first().json.listing_id;
const names = $('Prep Properties').all().map(i => i.json.name);
const errText = e => (typeof e === 'string' ? e : JSON.stringify(e)).slice(0, 200);
const propErrors = $('Set Property').all().map((i, k) => i.json.error ? names[k] + ': ' + errText(i.json.error) : null).filter(Boolean);
const skuRes = $input.first().json;
if (skuRes.error) propErrors.push('sku: ' + errText(skuRes.error));
return p.images.map(x => ({ json: { listing_id: lid, url: x.url, rank: x.rank, label: x.label, propErrors } }));

const friendly = e => { const t = typeof e === 'string' ? e : JSON.stringify(e); return /binary file/i.test(t) ? 'the image could not be downloaded (the link in the sheet may be dead)' : t.slice(0, 200); };
const items = $input.all().map(i => i.json);
const prep = $('Prep Images').all().map(i => i.json);
const uploaded = items.filter(x => x.listing_image_id).length;
const bad = items.map((x, k) => x.error ? { label: prep[k].label, rank: prep[k].rank, url: prep[k].url, error: friendly(x.error) } : null).filter(Boolean);
return [{ json: { listing_id: prep[0].listing_id, uploaded, failedItems: bad, failed: bad.map(b => b.label + ': ' + b.error), propErrors: prep[0].propErrors } }];

const p = $('Pick Row').first().json;
const created = $('Create Draft').first().json;
const coll = $('Collect Uploads').first().json;
let retry = null; try { retry = $('Collect Retry').first().json; } catch (e) { retry = null; }
const failedFinal = retry ? retry.failedAfterRetry : coll.failed;
const v = $input.first().json;
const results = (v.results || []).slice().sort((a, b) => a.rank - b.rank);
const errors = [];
if (coll.propErrors.length) errors.push('properties: ' + coll.propErrors.join('; '));
const notes = retry && retry.retried ? ['retried ' + retry.retried + ' image(s) in a second pass'] : [];
if (failedFinal.length) errors.push('images: ' + failedFinal.join('; '));
if (results.length !== p.expectedImages) errors.push('images on Etsy ' + results.length + ' of ' + p.expectedImages);
const ranksOk = results.every((x, i) => x.rank === i + 1);
if (!ranksOk) errors.push('image ranks are not 1..n');
const iso = ts => ts ? new Date(ts * 1000).toISOString() : '';
const vals = { etsylistingid: created.listing_id, etsyurl: created.url || '', etsyadminurl: 'https://www.etsy.com/your/shops/me/listing-editor/edit/' + created.listing_id, etsystatus: errors.length ? 'draft_with_errors' : 'draft', etsyerror: errors.join(' | '), etsycreatedat: iso(created.creation_timestamp || created.created_timestamp), etsypricecad: p.priceCad, etsycategoryid: p.taxonomyId, etsyimagecount: results.length, etsysyncedat: new Date().toISOString(), etsyreadytopost: 'no' };
const data = Object.entries(vals).map(([k, val]) => ({ range: "'" + p.tab.replace(/'/g, "''") + "'!" + p.writeCols[k] + p.row, values: [[val]] }));
return [{ json: { body: { valueInputOption: 'RAW', data }, summary: { sku: p.sku, tab: p.tab, row: p.row, listingId: created.listing_id, adminUrl: vals.etsyadminurl, status: vals.etsystatus, imagesOnEtsy: results.length, imagesExpected: p.expectedImages, errors, notes } } }];

const p = $('Pick Row').first().json;
const c = $input.first().json;
const msg = (c.error ? (typeof c.error === 'string' ? c.error : JSON.stringify(c.error)) : JSON.stringify(c)).slice(0, 500);
const vals = { etsystatus: 'create_failed', etsyerror: msg, etsysyncedat: new Date().toISOString() };
const data = Object.entries(vals).map(([k, val]) => ({ range: "'" + p.tab.replace(/'/g, "''") + "'!" + p.writeCols[k] + p.row, values: [[val]] }));
return [{ json: { body: { valueInputOption: 'RAW', data }, summary: { sku: p.sku, tab: p.tab, row: p.row, status: 'create_failed', errors: [msg] } } }];

const w = $input.first().json;
let s;
try { s = $('Build Write').first().json.summary; } catch (e) { s = $('Create Failed').first().json.summary; }
return [{ json: { dryRun: false, ...s, sheetCellsUpdated: w.totalUpdatedCells || 0, sheetError: w.error || null } }];

const friendly = e => { const t = typeof e === 'string' ? e : JSON.stringify(e); return /binary file/i.test(t) ? 'the image could not be downloaded (the link in the sheet may be dead)' : t.slice(0, 200); };
const items = $input.all().map(i => i.json);
const prep = $('Prep Retry').all().map(i => i.json);
const base = $('Collect Uploads').first().json;
const failedAfterRetry = items.map((x, k) => x.error ? prep[k].label + ': ' + friendly(x.error) : null).filter(Boolean);
return [{ json: { listing_id: base.listing_id, retried: prep.length, failedAfterRetry, propErrors: base.propErrors } }];

const p = $('Pick Row').first().json;
const cfg = $('Config').first().json;
const lid = $('Prep Properties').first().json.listing_id;
const body = { products: [{ sku: p.sku, property_values: [], offerings: [{ price: p.priceCad, quantity: p.quantity || 1, is_enabled: true, readiness_state_id: Number(cfg.readinessStateId) }] }], price_on_property: [], quantity_on_property: [], sku_on_property: [] };
return [{ json: { listing_id: lid, body } }];
